# The overlay files each patch of patches/ brings with it when the series
# is exported for upstream (scripts/qemu-tree export). Patches are named
# without their number, so renumbering the series needs no change here.
# Every file under overlay/ must be listed exactly once; patches that add
# no file are not listed.
#
# <patch name>: <overlay file>...

hw-misc-Add-the-Broadcom-RNG200-random-number-generator: hw/misc/bcm2711_rng200.c include/hw/misc/bcm2711_rng200.h
hw-intc-Add-the-Broadcom-STB-level-2-interrupt-controller: hw/intc/brcmstb_l2_intc.c include/hw/intc/brcmstb_l2_intc.h
hw-gpio-Add-the-Broadcom-STB-GPIO-controller: hw/gpio/brcmstb_gpio.c include/hw/gpio/brcmstb_gpio.h
hw-gpio-Add-the-Broadcom-STB-pin-controller: hw/gpio/brcmstb_pinctrl.c include/hw/gpio/brcmstb_pinctrl.h
hw-i2c-Add-the-Broadcom-STB-BSC-I2C-controller: hw/i2c/brcmstb_i2c.c include/hw/i2c/brcmstb_i2c.h
hw-sd-Add-the-Broadcom-BCM2712-SD-host-controller: hw/sd/bcm2712_sdhci.c include/hw/sd/bcm2712_sdhci.h
hw-misc-Add-the-Broadcom-AVS-monitor: hw/misc/bcm2711_avs_monitor.c include/hw/misc/bcm2711_avs_monitor.h
hw-misc-Add-the-Raspberry-Pi-5-firmware-s-property-interface: hw/misc/bcm2712_property.c include/hw/misc/bcm2712_property.h
hw-misc-Add-the-Broadcom-STB-reset-controllers: hw/misc/brcmstb_reset.c include/hw/misc/brcmstb_reset.h
hw-pci-host-Add-the-Broadcom-STB-PCIe-root-complex: hw/pci-host/brcmstb_pcie.c include/hw/pci-host/brcmstb_pcie.h
hw-intc-Add-the-Broadcom-BCM2712-MIP-MSI-controller: hw/intc/bcm2712_mip.c include/hw/intc/bcm2712_mip.h
hw-arm-Add-the-Broadcom-BCM2712-SoC: hw/arm/bcm2712.c include/hw/arm/bcm2712.h
hw-arm-Add-the-Raspberry-Pi-5-Model-B-machine: hw/arm/raspi5b.c
tests-qtest-Add-tests-for-the-raspi5b-machine: tests/qtest/raspi5b-test.c
docs-system-arm-Document-the-raspi5b-machine: docs/system/arm/raspi5b.rst
